#!/usr/bin/env node
/**
 * Stamp the git commit count into `libs/version/generated/build-number.ts`.
 *
 * The number is the count of commits reachable from HEAD, so it advances by one
 * per merged pull request and is stable for a given checkout. It is written to a
 * generated file that both build configurations swap in through
 * `fileReplacements`, so the committed `build-number.ts` (always `0`) is never
 * modified and a build leaves the working tree clean.
 *
 * CI checks out with `fetch-depth: 0`; a shallow clone would report a smaller
 * count, which is why the script fails loudly rather than stamping a wrong number
 * when the history looks truncated.
 */
const {execFileSync} = require('node:child_process');
const {mkdirSync, writeFileSync} = require('node:fs');
const {join} = require('node:path');

const root = join(__dirname, '..');

const run = (args) => execFileSync('git', args, {cwd: root, encoding: 'utf8'}).trim();

if (run(['rev-parse', '--is-shallow-repository']) === 'true') {
  console.error(
    'The repository is a shallow clone, so the commit count would be wrong. ' +
      'Run `git fetch --unshallow` before building.'
  );
  process.exit(1);
}

const buildNumber = run(['rev-list', '--count', 'HEAD']);
const target = join(root, 'libs', 'version', 'generated', 'build-number.ts');

mkdirSync(join(root, 'libs', 'version', 'generated'), {recursive: true});
writeFileSync(
  target,
  '// Generated by tools/generate-version.js. Do not edit; do not commit.\n' +
    `export const BUILD_NUMBER = '${buildNumber}';\n`
);

console.log(`Stamped build number ${buildNumber} into ${target}`);
